17 | package com.ibm.jp.automation.e2m.maven;
18 | 
19 | import com.ibm.jp.automation.e2m.eclipse.EclipseProject;
20 | import com.ibm.jp.automation.e2m.i18n.Messages;
21 | import com.ibm.jp.automation.e2m.spec.JavaVersion;
22 | import com.ibm.jp.automation.e2m.util.AppLogger;
23 | 
24 | import org.slf4j.Logger;
25 | 
26 | import java.io.IOException;
27 | import java.nio.charset.Charset;
28 | import java.nio.charset.StandardCharsets;
29 | import java.nio.file.Files;
30 | import java.nio.file.Path;
31 | import java.nio.file.StandardCopyOption;
32 | import java.util.List;
33 | import java.util.regex.Matcher;
34 | import java.util.regex.Pattern;
35 | 
36 | /**
37 |  * EclipseプロジェクトのソースファイルをMavenの標準ディレクトリ構造にコピーするクラス。
38 |  *
39 |  * <ul>
40 |  *   <li>Javaソース (.java) → src/main/java/ または src/test/java/</li>
41 |  *   <li>リソースファイル (非.java) → src/main/resources/ または src/test/resources/</li>
42 |  *   <li>Webコンテンツ (WTPプロジェクトの場合) → src/main/webapp/</li>
43 |  * </ul>
44 |  *
45 |  * <p>{@code convertToUtf8} が {@code true} の場合、以下の変換を行う：</p>
46 |  * <ul>
47 |  *   <li>{@code .java} ファイル: {@code sourceEncoding} で読み込み、UTF-8 で書き出す</li>
48 |  *   <li>{@code .properties} ファイル: {@code sourceEncoding} で読み込み、Unicode エスケープを
49 |  *       Unicode 文字に展開して UTF-8 で書き出す。{@code effectiveTargetVersion <= 8} の場合は
50 |  *       {@code src/main/resources-utf8/} へ出力する</li>
51 |  *   <li>{@code .jsp} ファイル: {@code pageEncoding} 属性を検出してそのエンコードで読み込み、
52 |  *       属性値を {@code UTF-8} に書き換えて出力する</li>
53 |  * </ul>
54 |  */
55 | public class ProjectCopier {
56 | 
57 |     private static final Logger log = AppLogger.get(ProjectCopier.class);
58 | 
59 |     private ProjectCopier() {}
60 | 
61 |     /** ISO-8859-1 でプリアンブルを読む際のバッファサイズ（4KB）。 */
62 |     private static final int JSP_PREAMBLE_BYTES = 4096;
63 | 
64 |     /** JSP の pageEncoding 属性を検出する正規表現。 */
65 |     private static final Pattern JSP_PAGE_ENCODING_PATTERN =
66 |             Pattern.compile("<%@\\s*page\\b[^%]*\\bpageEncoding\\s*=\\s*[\"']([^\"']+)[\"']",
67 |                     Pattern.DOTALL);
68 | 
69 |     /** properties ファイルの Unicode エスケープシーケンスを検出する正規表現。 */
70 |     private static final Pattern UNICODE_ESCAPE_PATTERN =
71 |             Pattern.compile("\\\\u([0-9a-fA-F]{4})");
72 | 
73 |     /**
74 |      * EclipseプロジェクトのファイルをMaven標準ディレクトリ構造にコピーする。
75 |      *
76 |      * @param eclipseProject        パース済みEclipseプロジェクト情報
77 |      * @param dependencies          解決済み依存関係リスト（system スコープの JAR を libs/ にコピーする）
78 |      * @param inputDir              Eclipseプロジェクトのルートディレクトリ
79 |      * @param outputDir             Mavenプロジェクトの出力ルートディレクトリ
80 |      * @param convertToUtf8         true の場合はエンコーディング変換を行う
81 |      * @param sourceEncoding        変換元エンコーディング（convertToUtf8=false の場合は無視）
82 |      * @param effectiveTargetVersion 実効Javaターゲットバージョン（.properties 出力先の判定に使用）
83 |      * @throws IOException ファイルコピーに失敗した場合
84 |      */
85 |     public static void copy(EclipseProject eclipseProject, List<MavenDependency> dependencies,
86 |                             Path inputDir, Path outputDir,
87 |                             boolean convertToUtf8, Charset sourceEncoding,
88 |                             JavaVersion effectiveTargetVersion) throws IOException {
89 | 
90 |         // Javaソースフォルダのコピー
91 |         List<String> sourceFolders = eclipseProject.sourceFolders();
92 |         for (String sourceFolder : sourceFolders) {
93 |             Path srcPath = resolveSourcePath(inputDir, sourceFolder);
94 |             if (!Files.isDirectory(srcPath)) {
95 |                 log.warn(Messages.get("projectCopier.sourceFolderNotFound", srcPath));
96 |                 continue;
97 |             }
98 |             boolean isTest = isTestFolder(sourceFolder);
99 |             Path javaDestBase = outputDir.resolve(isTest ? "src/test/java" : "src/main/java");
100 |             // .properties の出力先: Java 9+ → src/main/resources/、Java 8以下 → src/main/resources-utf8/
101 |             boolean useUtf8ResourceDir = convertToUtf8 && !effectiveTargetVersion.isUnknown()
102 |                     && effectiveTargetVersion.compareTo(JavaVersion.Java8) <= 0;
103 |             Path resourceDestBase = outputDir.resolve(
104 |                     isTest ? "src/test/resources"
105 |                            : (useUtf8ResourceDir ? "src/main/resources-utf8" : "src/main/resources"));
106 |             Path resourceDestNormal = outputDir.resolve(isTest ? "src/test/resources" : "src/main/resources");
107 | 
108 |             copySourceFolder(srcPath, srcPath, javaDestBase, resourceDestBase, resourceDestNormal,
109 |                     convertToUtf8, sourceEncoding);
110 |         }
111 | 
112 |         // Webコンテンツのコピー（WTPプロジェクトの場合）
113 |         if (eclipseProject.webProject() && eclipseProject.webContentRoot() != null) {
114 |             Path webContentPath = resolveSourcePath(inputDir, eclipseProject.webContentRoot());
115 |             if (Files.isDirectory(webContentPath)) {
116 |                 Path webappDest = outputDir.resolve("src/main/webapp");
117 |                 copyWebContents(webContentPath, webappDest, convertToUtf8, sourceEncoding);
118 |                 log.info(Messages.get("projectCopier.copiedWebContent", webContentPath, webappDest));
119 |             } else {
120 |                 log.warn(Messages.get("projectCopier.webContentRootNotFound", webContentPath));
121 |             }
122 |         }
123 | 
124 |         // system スコープの JAR を libs/compile または libs/provided にコピー
125 |         for (MavenDependency dep : dependencies) {
126 |             if ("system".equals(dep.scope()) && dep.systemPath() != null) {
127 |                 Path src = Path.of(dep.systemPath());
128 |                 if (Files.isRegularFile(src)) {
129 |                     // exported=true → libs/compile（WARのWEB-INF/libに含める）
130 |                     // exported=false → libs/provided（WARには含めない）
131 |                     String subDir = dep.exported() ? "libs/compile" : "libs/provided";
132 |                     Path libsDir = outputDir.resolve(subDir);
133 |                     Files.createDirectories(libsDir);
134 |                     Path dest = libsDir.resolve(src.getFileName());
135 |                     Files.copy(src, dest, StandardCopyOption.REPLACE_EXISTING);
136 |                     log.debug("  Copied JAR to {}/: {}", subDir, dest.getFileName());
137 |                 }
138 |             }
139 |         }
140 |     }
141 | 
142 |     /**
143 |      * ソースフォルダ内のファイルを.javaとリソースに振り分けてコピーする。
144 |      *
145 |      * @param baseDir            コピー元のルート（相対パス計算の基点）
146 |      * @param currentDir         現在処理中のディレクトリ
147 |      * @param javaDestBase       .javaファイルのコピー先ベースディレクトリ
148 |      * @param resourceDest       リソースファイルのコピー先ベースディレクトリ（.properties はここへ）
149 |      * @param resourceDestNormal 通常のリソースコピー先（.properties 以外の非.javaファイルはここへ）
150 |      * @param convertToUtf8      true の場合はエンコーディング変換を行う
151 |      * @param sourceEncoding     変換元エンコーディング
152 |      * @throws IOException ファイルコピーに失敗した場合
153 |      */
154 |     private static void copySourceFolder(Path baseDir, Path currentDir, Path javaDestBase,
155 |                                          Path resourceDest, Path resourceDestNormal,
156 |                                          boolean convertToUtf8, Charset sourceEncoding)
157 |             throws IOException {
158 |         log.debug("  javaDestBase = {}", javaDestBase);
159 |         log.debug("  resourceDest = {}", resourceDest);
160 |         log.debug("  resourceDestNormal = {}", resourceDestNormal);
161 | 
162 |         Files.walk(currentDir)
163 |             .filter(Files::isRegularFile)
164 |             .forEach(srcFile -> {
165 |                 try {
166 |                     Path relative = baseDir.relativize(srcFile);
167 |                     String fileName = srcFile.getFileName().toString();
168 |                     boolean isJava = fileName.endsWith(".java");
169 |                     boolean isProperties = fileName.endsWith(".properties");
170 | 
171 |                     if (isJava) {
172 |                         Path destFile = javaDestBase.resolve(relative);
173 |                         Files.createDirectories(destFile.getParent());
174 |                         if (convertToUtf8) {
175 |                             copyWithEncodingConversion(srcFile, destFile, sourceEncoding);
176 |                             log.debug("  [Java:UTF-8変換] {}", relative);
177 |                         } else {
178 |                             Files.copy(srcFile, destFile, StandardCopyOption.REPLACE_EXISTING);
179 |                             log.debug("  [Java:バイナリコピー] {}", relative);
180 |                         }
181 |                     } else if (isProperties && convertToUtf8) {
182 |                         // .properties: Unicode エスケープ展開 + UTF-8 で resourceDest へ
183 |                         Path destFile = resourceDest.resolve(relative);
184 |                         Files.createDirectories(destFile.getParent());
185 |                         copyPropertiesWithConversion(srcFile, destFile, sourceEncoding);
186 |                         log.debug("  [Properties:UTF-8変換] {}", relative);
187 |                     } else {
188 |                         // その他のリソース（バイナリコピー）
189 |                         Path destFile = resourceDestNormal.resolve(relative);
190 |                         Files.createDirectories(destFile.getParent());
191 |                         Files.copy(srcFile, destFile, StandardCopyOption.REPLACE_EXISTING);
192 |                         log.debug("  [Resource:バイナリコピー] {}", relative);
193 |                     }
194 |                 } catch (IOException e) {
195 |                     throw new RuntimeException("ファイルコピーに失敗しました: " + srcFile, e);
196 |                 }
197 |             });
198 |         log.info(Messages.get("projectCopier.copiedSourceFolder", currentDir, javaDestBase));
199 |     }
200 | 
201 |     /**
202 |      * Webコンテンツディレクトリを再帰的にコピーする。
203 |      * WEB-INF/lib 直下の .jar ファイルはスキップする。
204 |      * WEB-INF/classes ディレクトリ以下のファイルはすべてスキップする。
205 |      * {@code convertToUtf8=true} の場合、.jsp ファイルはエンコーディング変換を行う。
206 |      *
207 |      * @param srcDir         コピー元ディレクトリ
208 |      * @param destDir        コピー先ディレクトリ
209 |      * @param convertToUtf8  true の場合はエンコーディング変換を行う
210 |      * @param sourceEncoding 変換元エンコーディング（.jsp の pageEncoding が不明な場合に使用）
211 |      * @throws IOException ファイルコピーに失敗した場合
212 |      */
213 |     private static void copyWebContents(Path srcDir, Path destDir,
214 |                                         boolean convertToUtf8, Charset sourceEncoding)
215 |             throws IOException {
216 |         Path excludeJarDir = srcDir.resolve("WEB-INF/lib");
217 |         Path excludeClassesDir = srcDir.resolve("WEB-INF/classes");
218 |         Files.walk(srcDir)
219 |                 .filter(srcPath -> (!srcPath.startsWith(excludeJarDir)
220 |                         || !srcPath.getFileName().toString().endsWith(".jar"))
221 |                         && !srcPath.startsWith(excludeClassesDir))
222 |                 .forEach(srcPath -> {
223 |                     try {
224 |                         Path relative = srcDir.relativize(srcPath);
225 |                         Path destPath = destDir.resolve(relative);
226 |                         if (Files.isDirectory(srcPath)) {
227 |                             Files.createDirectories(destPath);
228 |                             log.debug("  [ディレクトリー作成] {}", relative);
229 |                         } else {
230 |                             Files.createDirectories(destPath.getParent());
231 |                             String fileName = srcPath.getFileName().toString();
232 |                             if (convertToUtf8 && fileName.endsWith(".jsp")) {
233 |                                 Charset jspEncoding = extractJspPageEncoding(srcPath, sourceEncoding);
234 |                                 if (jspEncoding != null) {
235 |                                     copyJspWithConversion(srcPath, destPath, jspEncoding);
236 |                                     log.debug("  [JSP:UTF-8変換] {} (encode={})", relative, jspEncoding);
237 |                                 } else {
238 |                                     // pageEncoding が既に UTF-8 → バイナリコピー
239 |                                     Files.copy(srcPath, destPath, StandardCopyOption.REPLACE_EXISTING);
240 |                                     log.debug("  [JSP:バイナリコピー] {}", relative);
241 |                                 }
242 |                             } else {
243 |                                 Files.copy(srcPath, destPath, StandardCopyOption.REPLACE_EXISTING);
244 |                                 log.debug("  [Web:バイナリコピー] {}", relative);
245 |                             }
246 |                         }
247 |                     } catch (IOException e) {
248 |                         throw new RuntimeException("ファイルコピーに失敗しました: " + srcPath, e);
249 |                     }
250 |                 });
251 |     }
252 | 
253 |     /**
254 |      * テキストファイルを指定エンコードで読み込み、UTF-8 で書き出す。
255 |      *
256 |      * @param src  コピー元ファイル
257 |      * @param dest コピー先ファイル
258 |      * @param from 変換元エンコーディング
259 |      * @throws IOException ファイル読み書きに失敗した場合
260 |      */
261 |     static void copyWithEncodingConversion(Path src, Path dest, Charset from) throws IOException {
262 |         String content = Files.readString(src, from);
263 |         Files.writeString(dest, content, StandardCharsets.UTF_8);
264 |     }
265 | 
266 |     /**
267 |      * .properties ファイルを指定エンコードで読み込み、Unicode エスケープを展開して UTF-8 で書き出す。
268 |      *
269 |      * @param src  コピー元ファイル
270 |      * @param dest コピー先ファイル
271 |      * @param from 変換元エンコーディング
272 |      * @throws IOException ファイル読み書きに失敗した場合
273 |      */
274 |     static void copyPropertiesWithConversion(Path src, Path dest, Charset from) throws IOException {
275 |         List<String> lines = Files.readAllLines(src, from);
276 |         List<String> converted = lines.stream()
277 |                 .map(ProjectCopier::unescapeUnicode)
278 |                 .toList();
279 |         Files.write(dest, converted, StandardCharsets.UTF_8);
280 |     }
281 | 
282 |     /**
283 |      * 文字列中の Unicode エスケープシーケンス（&#92;uXXXX 形式）を Unicode 文字に展開する。
284 |      *
285 |      * @param line 入力文字列
286 |      * @return Unicode エスケープを展開した文字列
287 |      */
288 |     static String unescapeUnicode(String line) {
289 |         Matcher m = UNICODE_ESCAPE_PATTERN.matcher(line);
290 |         if (!m.find()) {
291 |             return line;
292 |         }
293 |         m.reset();
294 |         StringBuilder sb = new StringBuilder();
295 |         while (m.find()) {
296 |             int codePoint = Integer.parseInt(m.group(1), 16);
297 |             m.appendReplacement(sb, Matcher.quoteReplacement(String.valueOf((char) codePoint)));
298 |         }
299 |         m.appendTail(sb);
300 |         return sb.toString();
301 |     }
302 | 
303 |     /**
304 |      * JSP ファイルの先頭 4KB を ISO-8859-1 で読み込み、{@code pageEncoding} 属性を検出する。
305 |      *
306 |      * <ul>
307 |      *   <li>検出でき、かつ UTF-8 系でない場合: そのエンコーディングの {@link Charset} を返す</li>
308 |      *   <li>検出できない場合: {@code fallback} を返す</li>
309 |      *   <li>検出でき、かつ既に UTF-8 系の場合: {@code null} を返す（呼び出し元でバイナリコピーに切り替える）</li>
310 |      * </ul>
311 |      *
312 |      * @param jspFile  JSP ファイルのパス
313 |      * @param fallback pageEncoding が見つからない場合に返すエンコーディング
314 |      * @return 変換元エンコーディング、または null（既に UTF-8 の場合）
315 |      * @throws IOException ファイル読み込みに失敗した場合
316 |      */
317 |     static Charset extractJspPageEncoding(Path jspFile, Charset fallback) throws IOException {
318 |         // 先頭 4KB を ISO-8859-1 で読み込む（バイト値をそのまま文字として扱うため）
319 |         byte[] bytes = Files.readAllBytes(jspFile);
320 |         int len = Math.min(bytes.length, JSP_PREAMBLE_BYTES);
321 |         String preamble = new String(bytes, 0, len, StandardCharsets.ISO_8859_1);
322 | 
323 |         Matcher m = JSP_PAGE_ENCODING_PATTERN.matcher(preamble);
324 |         if (!m.find()) {
325 |             return fallback;
326 |         }
327 |         String encodingName = m.group(1).trim();
328 |         // 既に UTF-8 系であれば null を返す
329 |         if (encodingName.equalsIgnoreCase("UTF-8") || encodingName.equalsIgnoreCase("UTF8")) {
330 |             return null;
331 |         }
332 |         try {
333 |             return Charset.forName(encodingName);
334 |         } catch (Exception e) {
335 |             // 不明なエンコーディング名の場合は fallback を使用
336 |             log.warn(Messages.get("projectCopier.unknownJspPageEncoding", encodingName));
337 |             return fallback;
338 |         }
339 |     }
340 | 
341 |     /**
342 |      * JSP ファイルを指定エンコードで読み込み、{@code pageEncoding} 属性値を {@code UTF-8} に書き換えて出力する。
343 |      *
344 |      * @param src  コピー元 JSP ファイル
345 |      * @param dest コピー先ファイル
346 |      * @param from 変換元エンコーディング
347 |      * @throws IOException ファイル読み書きに失敗した場合
348 |      */
349 |     static void copyJspWithConversion(Path src, Path dest, Charset from) throws IOException {
350 |         String content = Files.readString(src, from);
351 |         // pageEncoding 属性値を UTF-8 に書き換える（シングルクォートとダブルクォートの両方に対応）
352 |         String converted = content.replaceAll(
353 |                 "(<%@\\s*page\\b[^%]*\\bpageEncoding\\s*=\\s*)([\"'])([^\"']+)\\2",
354 |                 "$1$2UTF-8$2");
355 |         Files.writeString(dest, converted, StandardCharsets.UTF_8);
356 |     }
357 | 
358 |     /**
359 |      * ソースフォルダのパス文字列をinputDir基点の絶対Pathに解決する。
360 |      * 先頭の '/' は除去して相対パスとして扱う。
361 |      */
362 |     private static Path resolveSourcePath(Path inputDir, String folderPath) {
363 |         String normalized = folderPath.startsWith("/") ? folderPath.substring(1) : folderPath;
364 |         if (normalized.isEmpty()) {
365 |             return inputDir;
366 |         }
367 |         return inputDir.resolve(normalized);
368 |     }
369 | 
370 |     /**
371 |      * ソースフォルダ名に "test" が含まれるかどうかを判定する。
372 |      * パスの各セグメントを小文字で比較する。
373 |      */
374 |     static boolean isTestFolder(String folderPath) {
375 |         String lower = folderPath.toLowerCase();
376 |         for (String segment : lower.split("[/\\\\]")) {
377 |             if (segment.equals("test") || segment.startsWith("test-") || segment.endsWith("-test")) {
378 |                 return true;
379 |             }
380 |         }
381 |         return false;
382 |     }
383 | }
